<!--
 * 角色管理页面 — 展示角色列表，支持新增/编辑/删除角色及权限分配
 *
 * @path apps\userinfo-web\src\views\system\role\index.vue
 * @author ydsz-team
 * @since 1.0.0
-->
<script lang="ts" setup>
/**
 * 角色（列表页）
 * <p>角色（{@code ydsz_role}）的列表页，消费后端契约 RoleController
 * （src/api/role.ts，auto-generated by bash/gen-contract.py）：
 * page() 分页查询角色，支持新增/编辑/删除，以及基于菜单树的权限分配
 * （getRolePermissions / assignPermissions，菜单来源 menu.tree()）。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import type { VxeTableGridOptions } from '@ydsz/plugins/vxe-table';

import { Page, useYdModal } from '@ydsz/common-ui';

import { YdBadge, YdButton, YdTable, YdTableColumn, YdDialog, YdTransfer } from '@ydsz-core/ydsz-ui';
import { h, onMounted, ref } from 'vue';
import { useI18n } from 'vue-i18n';

import { createLogger } from '@ydsz-core/shared/utils';

import { useYDSZVxeGrid } from '#/adapter/vxe-table';
import { tree as menuTree } from '#/api/menu';
import type { MenuTreeVO, UserAccountVO } from '#/api/models';
import { page as userPage } from '#/api/userAccount';
import { assignPermissions, create, getById, getRolePermissions, page, remove } from '#/api/role';
import type { RoleVO } from '#/api/models';

import RoleForm from './role-form.vue';

defineOptions({ name: 'RoleManagement' });

const logger = createLogger('userinfo-role');
const { t } = useI18n();

/** 判断角色状态是否启用（契约 status 为字符串 '1'/'0'） */
function isEnabled(status?: string): boolean {
  return status === '1';
}

const gridOptions: VxeTableGridOptions<RoleVO> = {
  columns: [
    { type: 'seq', width: 50, title: t('page.rowIndex') },
    { field: 'roleName', title: t('page.roleName'), width: 150 },
    { field: 'roleCode', title: t('page.roleCode'), width: 150 },
    { field: 'sort', title: t('page.sort'), width: 80, align: 'center' },
    {
      field: 'builtIn',
      title: t('role.builtIn'),
      width: 80,
      slots: {
        default: ({ row }) =>
          row.builtIn ? h(YdBadge, { variant: 'secondary', class: 'text-xs' }, () => t('role.yesBuiltIn')) : h('span', null, t('role.noBuiltIn')),
      },
    },
    {
      field: 'status',
      title: t('page.status'),
      width: 80,
      slots: {
        default: ({ row }) => {
          const enable = isEnabled(row.status);
          return h(
            YdBadge,
            { variant: enable ? 'default' : 'destructive', class: enable ? 'bg-green-500 text-white hover:bg-green-600' : 'text-xs' },
            () => (enable ? t('page.enabled') : t('page.disabled')),
          );
        },
      },
    },
    { field: 'description', title: t('page.description'), minWidth: 160 },
    {
      field: 'action',
      title: t('page.operation'),
      width: 320,
      fixed: 'right',
      slots: {
        default: ({ row }) =>
          h('div', { class: 'flex gap-1' }, [
            h(
              YdButton,
              { size: 'sm', variant: 'link', onClick: () => handleEdit(row) },
              () => t('page.edit'),
            ),
            h(
              YdButton,
              { size: 'sm', variant: 'link', class: 'border-yellow-500 text-yellow-600 dark:text-yellow-400', onClick: () => handleAssignPermissions(row) },
              () => t('role.assignPermissions'),
            ),
            h(
              YdButton,
              { size: 'sm', variant: 'ghost', onClick: () => handleCopyRole(row) },
              () => t('role.copy'),
            ),
            h(
              YdButton,
              { size: 'sm', variant: 'link', class: 'border-green-500 text-green-600 dark:text-green-400', onClick: () => handleViewUsers(row) },
              () => t('role.viewUsers'),
            ),
            h(
              YdButton,
              { size: 'sm', variant: 'link', class: 'text-destructive', onClick: () => handleDelete(row) },
              () => t('page.delete'),
            ),
          ]),
      },
    },
  ],
  height: 'auto',
  pagerConfig: { pageSize: 20, pageSizes: [10, 20, 50, 100] },
  proxyConfig: {
    ajax: {
      query: async (_page, formValues) => {
        const res = await page({ query: { ...formValues } });
        return { items: res.data ?? [], total: res.total ?? 0 };
      },
    },
  },
  toolbarConfig: { custom: true, refresh: { code: 'query' }, search: true, zoom: true },
};

const [Grid, gridApi] = useYDSZVxeGrid({
  gridOptions,
  formOptions: {
    schema: [
      {
        component: 'YdInput',
        componentProps: { placeholder: t('page.roleName') },
        fieldName: 'roleName',
        label: t('page.roleName'),
      },
      {
        component: 'YdInput',
        componentProps: { placeholder: t('page.roleCode') },
        fieldName: 'roleCode',
        label: t('page.roleCode'),
      },
      {
        component: 'YdSelectBase',
        componentProps: {
          placeholder: t('page.status'),
          options: [
            { label: t('page.enabled'), value: '1' },
            { label: t('page.disabled'), value: '0' },
          ],
        },
        fieldName: 'status',
        label: t('page.status'),
      },
    ],
    submitOnChange: false,
    collapsed: false,
    collapseTriggerResize: true,
    showCollapseButton: true,
    submitButtonOptions: { content: t('page.search') },
    resetButtonOptions: { content: t('page.reset') },
  },
});

// ========== 表单弹窗 ==========
const [RoleFormModal, roleFormApi] = useYdModal({ connectedComponent: RoleForm });

function handleAdd() {
  roleFormApi.open();
}

function handleEdit(row: RoleVO) {
  roleFormApi.setData({ record: row });
  roleFormApi.open();
}

// ========== 权限分配 ==========
const permDialogVisible = ref(false);
const currentRoleId = ref('');
const currentRoleName = ref('');
const selectedPermIds = ref<string[]>([]);
const permTransferData = ref<{ label: string; key: string }[]>([]);

/** 将菜单树拍平为穿梭框可选数据（label 展示菜单名+权限标识） */
function flattenMenuTree(nodes: MenuTreeVO[]): { label: string; key: string }[] {
  const result: { label: string; key: string }[] = [];
  nodes.forEach((node) => {
    if (node.id) {
      result.push({
        label: `${node.menuName ?? ''}${node.permissionCode ? ` (${node.permissionCode})` : ''}`,
        key: node.id,
      });
    }
    if (node.children?.length) {
      result.push(...flattenMenuTree(node.children));
    }
  });
  return result;
}

const menuTreeData = ref<MenuTreeVO[]>([]);

async function loadMenuTree() {
  try {
    menuTreeData.value = (await menuTree()) ?? [];
  } catch (error) {
    logger.warn('加载菜单树失败: {}', error);
  }
}

onMounted(loadMenuTree);

async function handleAssignPermissions(row: RoleVO) {
  if (!row.id) return;
  currentRoleId.value = row.id;
  currentRoleName.value = row.roleName ?? '';
  permTransferData.value = flattenMenuTree(menuTreeData.value);
  try {
    selectedPermIds.value = (await getRolePermissions({ roleId: row.id })) ?? [];
  } catch (error) {
    logger.warn('获取角色权限失败: {}', error);
  }
  permDialogVisible.value = true;
}

async function confirmPermissionAssign() {
  try {
    await assignPermissions(
      { roleId: currentRoleId.value },
      { permissionIds: selectedPermIds.value },
    );
    showToast.success(t('role.permissionAssignSuccess'));
    permDialogVisible.value = false;
  } catch (error) {
    logger.warn('分配权限失败: {}', error);
  }
}

// ========== 删除 ==========
async function handleDelete(row: RoleVO) {
  if (!row.id) return;
  // 步骤1：确认弹窗（用户取消直接返回）
  try {
    await YdConfirm(
      t('role.deleteRoleConfirm', { roleName: row.roleName ?? '' }),
      t('page.confirmDelete'),
      { type: 'warning' },
    );
  } catch {
    // 用户主动取消删除
    return;
  }
  // 步骤2：执行删除 API
  try {
    await remove({ id: row.id });
    showToast.success(t('page.deleteSuccess'));
    gridApi.query();
  } catch (error) {
    logger.warn('删除角色失败: {}', error);
  }
}

// ========== 复制角色 ==========
async function handleCopyRole(row: RoleVO): Promise<void> {
  if (!row.id) return;
  try {
    // 获取源角色详情
    const sourceRole = await getById({ id: row.id });
    // 创建新角色（复制属性，修改名称和编码）
    const newRoleId = await create({
      roleName: `${sourceRole.roleName ?? ''}_副本`,
      roleCode: `${sourceRole.roleCode ?? ''}_COPY_${Date.now()}`,
      description: sourceRole.description,
dataScope: sourceRole.dataScope,
status: sourceRole.status,
      tenantId: sourceRole.tenantId,
    });
    // 复制权限
    const permissions = await getRolePermissions({ roleId: row.id });
    if (permissions.length > 0 && newRoleId) {
      await assignPermissions({ roleId: newRoleId }, { permissionIds: permissions });
    }
    showToast.success(t('role.copySuccess'));
    gridApi.query();
  } catch (error) {
    logger.warn('复制角色失败: {}', error);
  }
}

// ========== 角色用户列表 ==========
const userListDialogVisible = ref(false);
const roleUserList = ref<UserAccountVO[]>([]);
const currentViewRoleName = ref('');

async function handleViewUsers(row: RoleVO): Promise<void> {
  if (!row.id) return;
  currentViewRoleName.value = row.roleName ?? '';
  userListDialogVisible.value = true;
  try {
    const res = await userPage({
      query: { roleIds: row.id },
    });
    roleUserList.value = res.data ?? [];
  } catch (error) {
    logger.warn('获取角色用户失败: {}', error);
    roleUserList.value = [];
  }
}
</script>

<template>
  <Page auto-content-height>
    <Grid :table-title="t('role.roleManagement')">
      <template #toolbar-tools>
        <YdButton variant="default" @click="handleAdd">{{ t('role.createRole') }}</YdButton>
      </template>
    </Grid>
    <RoleFormModal @success="gridApi.query()" />

    <YdDialog
      v-model="permDialogVisible"
      :title="t('role.assignPermissions') + ' - ' + currentRoleName"
      width="600px"
    >
      <YdTransfer
        v-model="selectedPermIds"
        :data="permTransferData"
        :titles="[t('role.optionalPermission'), t('role.assignedPermission')]"
        filterable
        :filter-placeholder="t('role.searchPermission')"
      />
      <template #footer>
        <YdButton variant="outline" @click="permDialogVisible = false">{{ t('page.cancel') }}</YdButton>
        <YdButton variant="default" @click="confirmPermissionAssign">{{ t('page.confirm') }}</YdButton>
      </template>
    </YdDialog>

    <!-- 角色用户列表弹窗 -->
    <YdDialog
      v-model="userListDialogVisible"
      :title="t('role.roleUsers') + ' - ' + currentViewRoleName"
      width="800px"
    >
      <YdTable :data="roleUserList" border max-height="400">
        <YdTableColumn type="index" :label="t('page.rowIndex')" width="60" />
        <YdTableColumn prop="username" :label="t('page.username')" width="120" />
        <YdTableColumn prop="realName" :label="t('page.realName')" width="120" />
        <YdTableColumn prop="phone" :label="t('page.phone')" width="130" />
        <YdTableColumn prop="email" :label="t('page.email')" width="180" />
        <YdTableColumn prop="status" :label="t('page.status')" width="80">
          <template #default="{ row }">
            <YdBadge :variant="row.status === 1 ? 'default' : 'destructive'" :class="row.status === 1 ? 'bg-green-500 text-white hover:bg-green-600' : 'text-xs'">
              {{ row.status === 1 ? t('page.enabled') : t('page.disabled') }}
            </YdBadge>
          </template>
        </YdTableColumn>
        <YdTableColumn prop="createdAt" :label="t('page.createTime')" width="170" />
      </YdTable>
      <template #footer>
        <YdButton variant="outline" @click="userListDialogVisible = false">{{ t('page.close') }}</YdButton>
      </template>
    </YdDialog>
  </Page>
</template>
